structlogger = structlog.get_logger()


class PydanticAICopilot:
    """Copilot v2 runtime — single-turn streaming with MCP read/write tools.

    When a ``thread_store`` is supplied, each completed turn is persisted via a
    native PydanticAI ``after_run`` hook so conversation history survives across
    requests and restarts.
    """

    def __init__(
        self,
        config: PydanticAIConfig | None = None,
        thread_store: "ThreadStore | None" = None,
    ) -> None:
        self._config = config or PydanticAIConfig()
        self._thread_store = thread_store
        # Triage layer: classify-then-route, gated exactly like v1. Flag off
        # means no classifier is built, no classification runs, and no
        # message_metadata event is ever emitted.
        self._classifier: MessageClassifier | None = (
            MessageClassifier(
                chat_history_size=builder_config.MESSAGE_CLASSIFIER_CHAT_HISTORY_SIZE
            )
            if builder_config.ORCHESTRATOR_ENABLED
            else None
        )
        self._last_user_message_context_prompt_template = Template(
            importlib.resources.read_text(
                f"{PACKAGE_NAME}.{COPILOT_PROMPTS_DIR}",
                COPILOT_LAST_USER_MESSAGE_CONTEXT_PROMPT_FILE_AGENT_SDK,
            )
        )
        self._agent: Agent[CopilotRunContext, str] = self._build_agent()

    async def stream_ag_ui_events(
        self,
        request: RunRequest,
        project_path: str | None = None,
        end_of_run_hook: EndOfRunHook | None = None,
        *,
        tracker_context_resolver: "TrackerContextResolver | None" = None,
    ) -> AsyncIterator[dict[str, object]]:
        """Run one Copilot v2 turn and yield its AG-UI events.

        After ``RUN_STARTED`` the turn is triaged: when the classifier decides a
        cheap category, the templated reply is streamed (plus a CUSTOM
        ``message_metadata`` event) and the turn is persisted here — the
        ``after_run`` hook never fires on a bypassed agent. Any triage failure
        degrades to the full agent path, which is byte-identical to the
        pre-triage stream.

        ``project_path`` is the server-resolved directory the file tools and the
        end-of-run commit hook operate on; it is never taken from the client.
        ``tracker_context_resolver`` is awaited with the request's session id
        only on the agent path — templated turns build no prompt to ground.
        """
        message_id = f"msg-{uuid.uuid4().hex}"
        yield ag_ui_events.run_started(request.thread_id, request.run_id)

        classification = await self._classify(request)
        if classification is not None and not classification.requires_full_copilot:
            try:
                async for event in self._stream_templated_turn(
                    request, classification.category, message_id
                ):
                    yield event
                yield ag_ui_events.run_finished(request.thread_id, request.run_id)
            except Exception as exc:
                yield ag_ui_events.run_error(str(exc), code=type(exc).__name__)
            return

        run_context = CopilotRunContext(request=request, project_path=project_path)
        mapper = AgUiEventMapper(message_id=message_id)
        await self._resolve_tracker_context(run_context, tracker_context_resolver)

        try:
            async for event in self._stream_runtime_events(
                request, run_context, mapper
            ):
                yield event

            # Flush any section the mapper left open (text or reasoning). On the
            # normal path this also runs before the end-of-run hook so the turn
            # is fully bracketed before any commit event.
            for event in mapper.close():
                yield event

            # End-of-run hook: runs after the turn completes, before RUN_FINISHED.
            if end_of_run_hook is not None:
                async for event in end_of_run_hook(run_context):
                    yield event
            yield ag_ui_events.run_finished(request.thread_id, request.run_id)
        except Exception as exc:
            # Close every open section (text and reasoning) before erroring so
            # the frontend is never left stuck mid-stream. ``close`` is
            # idempotent, so a section already flushed on the normal path above
            # yields nothing here.
            for event in mapper.close():
                yield event
            yield ag_ui_events.run_error(str(exc), code=type(exc).__name__)

    async def _classify(self, request: RunRequest) -> "MessageClassifierResult | None":
        """Triage the request; ``None`` means take the full agent path.

        The fail-open boundary is this whole step: adapter errors, classifier
        errors, and a request with no user turn all degrade to the agent path
        with a warning — a turn must never fail because of the triage layer.
        """
        if self._classifier is None:
            return None
        try:
            classification_request = _classification_request_from_run_request(request)
            if classification_request is None:
                structlogger.warning(
                    "copilot_v2.triage.no_user_turn",
                    thread_id=request.thread_id,
                )
                return None
            return await self._classifier.classify(classification_request)
        except Exception as exc:
            # Exception text can embed user content; log type + id only.
            structlogger.warning(
                "copilot_v2.triage.failed",
                error_type=type(exc).__name__,
                thread_id=request.thread_id,
            )
            return None

    async def _stream_templated_turn(
        self,
        request: RunRequest,
        category: "ResponseCategory",
        message_id: str,
    ) -> AsyncIterator[dict[str, object]]:
        """Resolve, persist, then stream the templated reply, tagged with category.

        The reply text is accumulated from the response module's own events
        (buffered, not yielded yet) so it stays the sole authority on reply
        content, including its missing-template fallback. Persistence happens
        *before* any event is exposed to the caller — mirroring the
        preflight's refused-turn path — so a client disconnect mid-stream can
        never drop the turn from the thread store. ``message_metadata`` is
        emitted after the text and before RUN_FINISHED — present iff the
        classifier served the turn.
        """
        buffered_events: list[dict[str, object]] = []
        reply_parts: list[str] = []
        async for event in classifier_response.stream_templated_reply(
            category, message_id
        ):
            if event["type"] == "TEXT_MESSAGE_CONTENT":
                reply_parts.append(str(event["delta"]))
            buffered_events.append(event)
        await self._persist_templated_turn(
            request, "".join(reply_parts), category, message_id
        )
        for event in buffered_events:
            yield event
        yield ag_ui_events.message_metadata(category.value)

    async def _persist_templated_turn(
        self,
        request: RunRequest,
        reply_text: str,
        category: "ResponseCategory",
        message_id: str,
    ) -> None:
        """Persist a classifier-served turn to the thread store, best-effort.

        The ``after_run`` hook never fires when the agent is bypassed, so the
        templated branch writes the user message and reply itself — the thread
        store is v2's source of truth and every user-visible reply must land in
        it. Same warn-and-continue contract as the hook.
        """
        if self._thread_store is None:
            return
        rows = rows_for_text_turn(
            user_text=trailing_user_text(request.messages),
            assistant_text=reply_text,
            response_category=category.value,
            assistant_message_id=message_id,
        )
        try:
            await self._thread_store.append_messages(request.thread_id, rows)
        except Exception as exc:
            structlogger.warning(
                "copilot_v2.templated_turn.persist_failed",
                error_type=type(exc).__name__,
                thread_id=request.thread_id,
            )

    async def _resolve_tracker_context(
        self,
        run_context: CopilotRunContext,
        tracker_context_resolver: "TrackerContextResolver | None",
    ) -> None:
        """Resolve tracker context onto the run context, degrading on failure.

        Runs only on the agent path, after RUN_STARTED, so the already-open SSE
        stream is never silent while the tracker store or the guardrails
        service round-trips. Any failure degrades to a context-free prompt —
        asking the Copilot must never fail because the Inspector session is
        stale or a dependency is down.
        """
        if tracker_context_resolver is None:
            return
        try:
            run_context.tracker_context = await tracker_context_resolver(
                run_context.request.session_id
            )
        except Exception as exc:
            # Exception text can embed user/tracker content; log type + id only.
            structlogger.warning(
                "copilot_v2.tracker_context.resolve_failed",
                error_type=type(exc).__name__,
                session_id=run_context.request.session_id,
            )

    def _render_last_user_message_context(
        self, run_context: CopilotRunContext
    ) -> str | None:
        """Render the tracker-context block for the final user turn.

        Returns ``None`` when there is neither tracker context nor attachments
        so the prompt stays byte-identical to a context-free run. The gate is
        on the inputs — not on formatter output truthiness — because
        ``format_conversation_history(None)`` returns a truthy empty-history
        JSON blob that would otherwise always render the section.
        """
        request = run_context.request
        if run_context.tracker_context is None and not request.attachments:
            return None
        return self._last_user_message_context_prompt_template.render(
            current_conversation=format_conversation_history(
                run_context.tracker_context
            ),
            current_state=format_current_state(run_context.tracker_context),
            attachments=format_tracker_event_attachments(list(request.attachments)),
        )

    def _build_agent(self) -> Agent[CopilotRunContext, str]:
        """Build the PydanticAI agent wired with MCP, file, and plan tools.

        When a thread store is configured, a native ``after_run`` hook is
        registered so the completed turn is persisted once the run finishes.
        """
        # TODO: drop this .filtered(...) once the MCP server stops exposing
        # search_rasa_documentation (i.e. once mcp_server/tools/document_search.py
        # is no longer needed by any MCP consumer). Excluded here so v2's own
        # agent doesn't see two tools of the same name: the local-retrieval
        # native tool registered below, and the MCP server's InKeep-backed one.
        server = MCPServerStreamableHTTP(self._config.mcp_url).filtered(
            lambda _ctx, tool_def: tool_def.name != TOOL_SEARCH_RASA_DOCUMENTATION
        )
        capabilities = []
        if self._thread_store is not None:
            capabilities.append(
                Hooks(after_run=build_persist_after_run_hook(self._thread_store))
            )
        agent = Agent(
            self._config.model_name,
            deps_type=CopilotRunContext,
            system_prompt=load_system_prompt(),
            output_type=str,
            toolsets=[server],
            capabilities=capabilities,
        )
        register_file_tools(agent)
        register_plan_tool(agent)
        register_document_search_tools(agent)
        return agent

    async def _stream_runtime_events(
        self,
        request: RunRequest,
        run_context: CopilotRunContext,
        mapper: AgUiEventMapper,
    ) -> AsyncIterator[dict[str, object]]:
        """Run PydanticAI and stream AG-UI text, reasoning, and tool-call events.

        Iterates the agent graph node-by-node. Both model-request nodes (which
        stream assistant text and reasoning) and call-tools nodes (which stream
        tool-call and tool-result events) are streamed so the AG-UI lifecycle
        stays faithful to the underlying agent loop. Translation to AG-UI events
        is delegated to ``mapper``; section bracketing and the final
        ``mapper.close()`` flush are owned by the caller so they also run when
        the loop raises mid-stream.

        After a successful ``update_plan`` result, a CUSTOM ``plan_update`` is
        yielded immediately so the frontend checklist updates in lockstep with
        the tool completion — no queue, no drain task.
        """
        prompt = _messages_to_prompt(
            request.messages, self._render_last_user_message_context(run_context)
        )
        effective_model_name = request.model or self._config.model_name
        effective_thinking = request.thinking
        resolved_model = resolve_model(effective_model_name, effective_thinking)
        model_settings = build_model_settings(effective_model_name, effective_thinking)

        # Only override the agent's configured model when the request asked for
        # a specific one, or reasoning forced a different resolution (e.g. the
        # OpenAI Responses model). Otherwise leave it None to use the default.
        model_override: Model | str | None = None
        if request.model is not None or resolved_model != effective_model_name:
            model_override = resolved_model

        async with self._agent:
            async with self._agent.iter(
                prompt,
                deps=run_context,
                model=model_override,
                model_settings=model_settings,
                usage_limits=UsageLimits(request_limit=self._config.max_model_requests),
            ) as agent_run:
                async for node in agent_run:
                    if not (
                        self._agent.is_model_request_node(node)
                        or self._agent.is_call_tools_node(node)
                    ):
                        continue
                    async with node.stream(agent_run.ctx) as node_stream:
                        async for event in node_stream:
                            for ag_event in mapper.map(event):
                                yield ag_event
                            if _is_successful_plan_result(event):
                                yield ag_ui_events.plan_update(
                                    run_context.plan.snapshot()
                                )


def _is_successful_plan_result(event: object) -> bool:
    """Return whether ``event`` is a successful ``update_plan`` tool result.

    A failed call arrives as ``RetryPromptPart`` and must not emit a plan
    event — the plan was not written.
    """
    return (
        isinstance(event, FunctionToolResultEvent)
        and isinstance(event.part, ToolReturnPart)
        and event.part.tool_name == PLAN_TOOL_NAME
    )


def _render_turn(message: Message, context: str | None = None) -> str:
    """Render one chat turn; ``context`` is spliced before the text when given."""
    if context is None:
        return f"{message.role}: {message.content}"
    return f"{message.role}: {context}\n\n{message.content}"


def _last_user_turn_index(messages: tuple[Message, ...]) -> int | None:
    """Index of the final user turn, scanning backwards; ``None`` without one."""
    return next(
        (
            index
            for index in range(len(messages) - 1, -1, -1)
            if messages[index].role == "user"
        ),
        None,
    )


def _classification_request_from_run_request(
    request: RunRequest,
) -> ClassificationRequest | None:
    """Build the classifier's neutral input from an AG-UI run request.

    Mirrors v1 exactly: the request is classifiable only when its literal
    final message is a user turn (v1's ``get_last_user_message`` requires the
    literal last history element to be the user's). A request that ends on an
    assistant turn — a client resending already-answered/rehydrated history —
    has nothing new to triage. System turns are excluded from history,
    mirroring v1's user/copilot-only classifier history. ``None`` means there
    is nothing to classify — the caller degrades to the agent path.
    """
    if not request.messages or request.messages[-1].role != "user":
        return None
    return ClassificationRequest(
        turns=tuple(
            ClassificationTurn(role=message.role, content=message.content)
            for message in request.messages
            if message.role in ("user", "assistant")
        ),
        attachments=request.attachments,
    )


def _messages_to_prompt(
    messages: tuple[Message, ...],
    last_user_message_context: str | None = None,
) -> str:
    """Render chat history into a prompt string for the model.

    When ``last_user_message_context`` is provided it is spliced inside the final
    user turn, immediately before the user's text — mirroring v1's placement
    so the block stays role-attributed in the flattened prompt. The final user
    turn is found by scanning backwards (the last element can be an assistant
    message). With no user turn anywhere there is no question to ground:
    injection is skipped with a warning and the run proceeds.
    """
    context_index: int | None = None
    if last_user_message_context is not None:
        context_index = _last_user_turn_index(messages)
        if context_index is None:
            structlogger.warning("copilot_v2.prompt.no_user_turn_for_tracker_context")
    return "\n\n".join(
        _render_turn(
            message,
            last_user_message_context if index == context_index else None,
        )
        for index, message in enumerate(messages)
    )
